// Common Spring Boot logging aspect example
@Aspect
@Component
public class LoggingAspect {
    private static final Logger log = LoggerFactory.getLogger(LoggingAspect.class);

    @Around("execution(* com.example.service.*.*(..))")
    public Object logMethodExecution(ProceedingJoinPoint joinPoint) throws Throwable {
        String methodName = joinPoint.getSignature().getName();
        log.info("Beginning execution of {}", methodName);

        long start = System.currentTimeMillis();
        Object result = joinPoint.proceed();
        long executionTime = System.currentTimeMillis() - start;

        log.info("{} executed in {}ms", methodName, executionTime);
        return result;
    }

    @AfterThrowing(pointcut = "execution(* com.example.service.*.*(..))" , throwing = "exception")
    public void logException(JoinPoint joinPoint, Exception exception) {
        log.error("Exception in {}.{}: {}",
            joinPoint.getSignature().getDeclaringTypeName(),
            joinPoint.getSignature().getName(),
            exception.getMessage());
    }
}

// Performance monitoring aspect for transactions
@Aspect
@Component
public class TransactionMonitoringAspect {
    private static final Logger log = LoggerFactory.getLogger(TransactionMonitoringAspect.class);

    @Around("@annotation(org.springframework.transaction.annotation.Transactional)")
    public Object monitorTransactionPerformance(ProceedingJoinPoint joinPoint) throws Throwable {
        String methodName = joinPoint.getSignature().getName();
        log.info("Beginning transaction in method: {}", methodName);

        long start = System.currentTimeMillis();
        Object result = joinPoint.proceed();
        long duration = System.currentTimeMillis() - start;

        log.info("Transaction completed in {}ms for method: {}", duration, methodName);
        return result;
    }
}

@Before("execution(* com.example.service.*.*(..))")
public void logBefore(JoinPoint joinPoint) {
    System.out.println("Before executing: " + joinPoint.getSignature().getName());
}

@Around("execution(* com.example.service.*.*(..))")
public Object logAround(ProceedingJoinPoint joinPoint) throws Throwable {
    long start = System.currentTimeMillis();

    Object result = joinPoint.proceed();

    long end = System.currentTimeMillis();
    System.out.println("Time taken: " + (end - start) + "ms");

    return result;
}

@Aspect
@Component
public class LoggingAspect {

    // Define pointcut
    @Pointcut("execution(* com.example.service.*.*(..))")
    public void serviceMethods() {}

    // Before advice
    @Before("serviceMethods()")
    public void logBefore(JoinPoint joinPoint) {
        System.out.println("Before executing: " + joinPoint.getSignature().getName());
    }

    // Around advice
    @Around("@annotation(com.example.annotation.LogExecutionTime)")
    public Object logExecutionTime(ProceedingJoinPoint joinPoint) throws Throwable {
        long start = System.currentTimeMillis();

        Object result = joinPoint.proceed();

        long end = System.currentTimeMillis();
        System.out.println("Time taken: " + (end - start) + "ms");

        return result;
    }
}

